import {FISH} from './fishing-data.js';
import {LESSONS} from './adventure-data.js';
export const MODES={meaning:'意味をつなぐ',reverse:'英語でこたえる',context:'文の中で使う',listen:'耳で見つける',spell:'文字で伝える',speak:'声で伝える'};
export const normalize=s=>String(s).normalize('NFKC').toLowerCase().replace(/[.,!?。！？]/g,'').trim().replace(/\s+/g,' ');
export function questionFor(id,mode='meaning',random=Math.random){const q=LESSONS[id];if(!q)throw new Error('学習することばが見つかりません');if(!MODES[mode])mode='meaning';const pool=FISH.filter(x=>x.grade===q.grade&&x.id!==id),selected=[q];while(selected.length<4&&pool.length)selected.push(pool.splice(Math.min(pool.length-1,Math.floor(random()*pool.length)),1)[0]);for(let i=selected.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[selected[i],selected[j]]=[selected[j],selected[i]]}return {...q,mode,options:selected.map(f=>({id:f.id,label:['meaning','listen'].includes(mode)?f.meaning:f.word})),text:mode==='listen'?'音を聞いて、意味を選ぼう':mode==='context'?q.context:['reverse','spell','speak'].includes(mode)?q.meaning:q.word};}
export function matchesAnswer(q,value){return ['spell','speak'].includes(q.mode)?normalize(value)===normalize(q.word):value===q.id;}
export function selectWord({grade='auto',regionWords=[],due=[],round=0,target=null,random=Math.random}){const targetGrade=grade==='auto'?(LESSONS[target]?.grade||LESSONS[regionWords[0]]?.grade||'5'):grade;if(round===0&&target&&grade==='auto')return target;const overdue=due.filter(id=>LESSONS[id]?.grade===targetGrade);if(overdue.length&&round%2===1)return overdue[round%overdue.length];const local=regionWords.filter(id=>LESSONS[id]?.grade===targetGrade);const pool=local.length?local:FISH.filter(f=>f.grade===targetGrade).map(f=>f.id);return pool[(round+Math.floor(random()*pool.length))%pool.length];}
